
-- ============================================================
-- DUMP SQL - Ultimate DJ
-- Projet : Gestion des prestations DJ et animation événementielle
-- SGBD cible : MySQL 8 / MariaDB 10.5+
-- Encodage : utf8mb4
-- Schéma synchronisé avec les migrations Django jusqu'à :
--   bookings.0003_quote_music_preferences
--   payments.0003_alter_payment_stripe_payment_intent_id
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS `ultimate_dj`;
CREATE DATABASE `ultimate_dj`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE `ultimate_dj`;

CREATE TABLE `languages` (
  `id` TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(5) NOT NULL,
  `name` VARCHAR(60) NOT NULL,
  `is_default` BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_languages_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `roles` (
  `id` TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(30) NOT NULL,
  `label` VARCHAR(60) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_roles_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `users` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `role_id` TINYINT UNSIGNED NOT NULL,
  `language_id` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `email` VARCHAR(190) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `first_name` VARCHAR(80) NOT NULL,
  `last_name` VARCHAR(80) NOT NULL,
  `phone` VARCHAR(30) NULL,
  `date_of_birth` DATE NULL,
  `is_active` BOOLEAN NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_email` (`email`),
  KEY `idx_users_role` (`role_id`),
  KEY `idx_users_language` (`language_id`),
  CONSTRAINT `fk_users_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`),
  CONSTRAINT `fk_users_language` FOREIGN KEY (`language_id`) REFERENCES `languages` (`id`),
  CONSTRAINT `chk_users_birth_major_or_null` CHECK (`date_of_birth` IS NULL OR `date_of_birth` <= '2008-07-04')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `client_profiles` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` INT UNSIGNED NOT NULL,
  `billing_address` VARCHAR(255) NOT NULL,
  `billing_city` VARCHAR(80) NOT NULL,
  `billing_postal_code` VARCHAR(20) NOT NULL,
  `vat_number` VARCHAR(30) NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_client_profiles_user` (`user_id`),
  KEY `idx_client_city` (`billing_city`),
  CONSTRAINT `fk_client_profiles_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `dj_profiles` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` INT UNSIGNED NOT NULL,
  `stage_name` VARCHAR(100) NOT NULL,
  `bio` TEXT NOT NULL,
  `base_hourly_rate` DECIMAL(10,2) NOT NULL,
  `travel_rate_per_km` DECIMAL(10,2) NOT NULL DEFAULT 0.60,
  `years_experience` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `is_available` BOOLEAN NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dj_profiles_user` (`user_id`),
  UNIQUE KEY `uk_dj_profiles_stage_name` (`stage_name`),
  KEY `idx_dj_available` (`is_available`),
  CONSTRAINT `fk_dj_profiles_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_dj_rate_positive` CHECK (`base_hourly_rate` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `event_types` (
  `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(80) NOT NULL,
  `requires_preparatory_meeting` BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_event_types_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `music_styles` (
  `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(80) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_music_styles_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `dj_music_styles` (
  `dj_profile_id` INT UNSIGNED NOT NULL,
  `music_style_id` SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (`dj_profile_id`, `music_style_id`),
  CONSTRAINT `fk_dj_music_styles_dj` FOREIGN KEY (`dj_profile_id`) REFERENCES `dj_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dj_music_styles_style` FOREIGN KEY (`music_style_id`) REFERENCES `music_styles` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `packages` (
  `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL,
  `description` VARCHAR(255) NOT NULL,
  `included_hours` DECIMAL(4,1) NOT NULL,
  `base_price` DECIMAL(10,2) NOT NULL,
  `is_active` BOOLEAN NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_packages_name` (`name`),
  CONSTRAINT `chk_packages_price_positive` CHECK (`base_price` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `service_options` (
  `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL,
  `price_type` ENUM('fixed','hourly') NOT NULL DEFAULT 'fixed',
  `unit_price` DECIMAL(10,2) NOT NULL,
  `is_active` BOOLEAN NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_service_options_name` (`name`),
  CONSTRAINT `chk_service_options_price_positive` CHECK (`unit_price` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `equipment` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `category` VARCHAR(60) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `serial_number` VARCHAR(80) NOT NULL,
  `daily_cost` DECIMAL(10,2) NOT NULL,
  `replacement_value` DECIMAL(10,2) NOT NULL,
  `status` ENUM('available','maintenance','reserved') NOT NULL DEFAULT 'available',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_equipment_serial` (`serial_number`),
  KEY `idx_equipment_category_status` (`category`, `status`),
  CONSTRAINT `chk_equipment_cost_positive` CHECK (`daily_cost` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `venues` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `client_profile_id` INT UNSIGNED NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `street` VARCHAR(160) NOT NULL,
  `postal_code` VARCHAR(20) NOT NULL,
  `city` VARCHAR(80) NOT NULL,
  `country` VARCHAR(80) NOT NULL DEFAULT 'Belgique',
  `has_parking` BOOLEAN NOT NULL DEFAULT 0,
  `distance_km_from_base` DECIMAL(6,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_venues_city` (`city`),
  KEY `idx_venues_client` (`client_profile_id`),
  CONSTRAINT `fk_venues_client` FOREIGN KEY (`client_profile_id`) REFERENCES `client_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_venues_distance_positive` CHECK (`distance_km_from_base` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `dj_availabilities` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `dj_profile_id` INT UNSIGNED NOT NULL,
  `available_date` DATE NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `status` ENUM('available','reserved','blocked') NOT NULL DEFAULT 'available',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dj_slot` (`dj_profile_id`, `available_date`, `start_time`),
  KEY `idx_availability_search` (`available_date`, `status`),
  CONSTRAINT `fk_availability_dj` FOREIGN KEY (`dj_profile_id`) REFERENCES `dj_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_availability_time` CHECK (`end_time` > `start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `quotes` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `client_profile_id` INT UNSIGNED NOT NULL,
  `event_type_id` SMALLINT UNSIGNED NOT NULL,
  `package_id` SMALLINT UNSIGNED NOT NULL,
  `venue_id` INT UNSIGNED NOT NULL,
  `preferred_language_id` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `event_date` DATE NOT NULL,
  `start_time` TIME NOT NULL,
  `duration_hours` DECIMAL(4,1) NOT NULL,
  `guest_count` SMALLINT UNSIGNED NOT NULL,
  `distance_km` DECIMAL(6,2) NOT NULL,
  `parking_available` BOOLEAN NOT NULL DEFAULT 0,
  `status` ENUM('draft','sent','accepted','refused','expired') NOT NULL DEFAULT 'draft',
  `subtotal` DECIMAL(10,2) NOT NULL,
  `travel_fee` DECIMAL(10,2) NOT NULL,
  `total_amount` DECIMAL(10,2) NOT NULL,
  `deposit_amount` DECIMAL(10,2) NOT NULL,
  `music_preferences` TEXT NOT NULL DEFAULT '',
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_quotes_client` (`client_profile_id`),
  KEY `idx_quotes_event_date` (`event_date`),
  CONSTRAINT `fk_quotes_client` FOREIGN KEY (`client_profile_id`) REFERENCES `client_profiles` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_quotes_event_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_quotes_package` FOREIGN KEY (`package_id`) REFERENCES `packages` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_quotes_venue` FOREIGN KEY (`venue_id`) REFERENCES `venues` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_quotes_language` FOREIGN KEY (`preferred_language_id`) REFERENCES `languages` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_quotes_amounts` CHECK (`total_amount` >= 0 AND `deposit_amount` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `quote_options` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `quote_id` INT UNSIGNED NOT NULL,
  `service_option_id` SMALLINT UNSIGNED NOT NULL,
  `quantity` SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `unit_price` DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quote_option` (`quote_id`, `service_option_id`),
  CONSTRAINT `fk_quote_options_quote` FOREIGN KEY (`quote_id`) REFERENCES `quotes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_quote_options_option` FOREIGN KEY (`service_option_id`) REFERENCES `service_options` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_quote_options_quantity` CHECK (`quantity` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `bookings` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `quote_id` INT UNSIGNED NOT NULL,
  `client_profile_id` INT UNSIGNED NOT NULL,
  `dj_profile_id` INT UNSIGNED NOT NULL,
  `event_type_id` SMALLINT UNSIGNED NOT NULL,
  `package_id` SMALLINT UNSIGNED NOT NULL,
  `venue_id` INT UNSIGNED NOT NULL,
  `event_date` DATE NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `status` ENUM('preparatory_meeting','confirmed','performed','paid','cancelled') NOT NULL,
  `total_amount` DECIMAL(10,2) NOT NULL,
  `deposit_required` DECIMAL(10,2) NOT NULL,
  `deposit_paid` BOOLEAN NOT NULL DEFAULT 0,
  `cancellation_reason` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bookings_quote` (`quote_id`),
  UNIQUE KEY `uk_booking_dj_slot` (`dj_profile_id`, `event_date`, `start_time`),
  KEY `idx_bookings_status` (`status`),
  KEY `idx_bookings_client` (`client_profile_id`),
  CONSTRAINT `fk_bookings_quote` FOREIGN KEY (`quote_id`) REFERENCES `quotes` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_bookings_client` FOREIGN KEY (`client_profile_id`) REFERENCES `client_profiles` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_bookings_dj` FOREIGN KEY (`dj_profile_id`) REFERENCES `dj_profiles` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_bookings_event_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_bookings_package` FOREIGN KEY (`package_id`) REFERENCES `packages` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_bookings_venue` FOREIGN KEY (`venue_id`) REFERENCES `venues` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_bookings_time` CHECK (`end_time` > `start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `booking_equipment` (
  `booking_id` INT UNSIGNED NOT NULL,
  `equipment_id` INT UNSIGNED NOT NULL,
  `quantity` SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`booking_id`, `equipment_id`),
  CONSTRAINT `fk_booking_equipment_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_booking_equipment_equipment` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_booking_equipment_quantity` CHECK (`quantity` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `contracts` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `booking_id` INT UNSIGNED NOT NULL,
  `contract_number` VARCHAR(40) NOT NULL,
  `status` ENUM('draft','sent','signed','cancelled') NOT NULL DEFAULT 'draft',
  `refund_policy` VARCHAR(255) NOT NULL,
  `signed_by_client_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_contract_booking` (`booking_id`),
  UNIQUE KEY `uk_contract_number` (`contract_number`),
  CONSTRAINT `fk_contracts_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `invoices` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `booking_id` INT UNSIGNED NOT NULL,
  `invoice_number` VARCHAR(40) NOT NULL,
  `invoice_type` ENUM('deposit','balance','full') NOT NULL,
  `amount` DECIMAL(10,2) NOT NULL,
  `status` ENUM('draft','sent','paid','cancelled') NOT NULL DEFAULT 'draft',
  `issued_at` DATETIME NOT NULL,
  `due_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_invoice_number` (`invoice_number`),
  KEY `idx_invoices_booking` (`booking_id`),
  KEY `idx_invoices_status` (`status`),
  CONSTRAINT `fk_invoices_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_invoices_amount` CHECK (`amount` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `payments` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `booking_id` INT UNSIGNED NOT NULL,
  `invoice_id` INT UNSIGNED NOT NULL,
  `stripe_session_id` VARCHAR(190) NOT NULL,
  `stripe_payment_intent_id` VARCHAR(190) NULL,
  `amount` DECIMAL(10,2) NOT NULL,
  `currency` CHAR(3) NOT NULL DEFAULT 'EUR',
  `status` ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',
  `paid_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payment_session` (`stripe_session_id`),
  UNIQUE KEY `uk_payment_intent` (`stripe_payment_intent_id`),
  KEY `idx_payments_booking` (`booking_id`),
  KEY `idx_payments_invoice` (`invoice_id`),
  CONSTRAINT `fk_payments_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_payments_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_payments_amount` CHECK (`amount` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `playlists` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `booking_id` INT UNSIGNED NOT NULL,
  `main_style_id` SMALLINT UNSIGNED NOT NULL,
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_playlist_booking` (`booking_id`),
  CONSTRAINT `fk_playlists_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_playlists_style` FOREIGN KEY (`main_style_id`) REFERENCES `music_styles` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `playlist_songs` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `playlist_id` INT UNSIGNED NOT NULL,
  `title` VARCHAR(160) NOT NULL,
  `artist` VARCHAR(120) NOT NULL,
  `preference_level` ENUM('must_play','play_if_possible','do_not_play') NOT NULL DEFAULT 'play_if_possible',
  `status` ENUM('requested','approved','rejected') NOT NULL DEFAULT 'requested',
  PRIMARY KEY (`id`),
  KEY `idx_playlist_songs_playlist` (`playlist_id`),
  CONSTRAINT `fk_playlist_songs_playlist` FOREIGN KEY (`playlist_id`) REFERENCES `playlists` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `reviews` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `booking_id` INT UNSIGNED NOT NULL,
  `client_profile_id` INT UNSIGNED NOT NULL,
  `dj_profile_id` INT UNSIGNED NOT NULL,
  `rating` TINYINT UNSIGNED NOT NULL,
  `comment` VARCHAR(255) NOT NULL,
  `status` ENUM('pending','published','rejected') NOT NULL DEFAULT 'pending',
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_booking` (`booking_id`),
  KEY `idx_reviews_dj` (`dj_profile_id`),
  CONSTRAINT `fk_reviews_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_reviews_client` FOREIGN KEY (`client_profile_id`) REFERENCES `client_profiles` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_reviews_dj` FOREIGN KEY (`dj_profile_id`) REFERENCES `dj_profiles` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_reviews_rating` CHECK (`rating` BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;


SET FOREIGN_KEY_CHECKS = 0;

